<script setup lang="ts">
const props=withDefaults(defineProps<{accountId:string;target?:string;compact?:boolean}>(),{target:'',compact:false});const {api,path,run,loading,errors}=useAuthorizationWorkspace(()=>props.accountId)
const events=ref<any[]>([]),cursor=ref<string|null>(null),model=ref<string[]>([]),action=ref(''),actor=ref(''),targetFilter=ref(''),start=ref(''),end=ref(''),selected=ref<any>(null)
async function load(append=false){const params=new URLSearchParams();params.set('limit',props.compact?'20':'50');if(append&&cursor.value)params.set('cursor',cursor.value);if(props.target||targetFilter.value)params.set('target',props.target||targetFilter.value);if(action.value)params.set('action',action.value);if(actor.value)params.set('actor',actor.value);if(start.value)params.set('start',new Date(start.value).toISOString());if(end.value)params.set('end',new Date(end.value).toISOString());model.value.forEach(v=>params.append('model',v));const data:any=await run('audit',()=>api(path(`authorization/audit?${params}`)));if(data){events.value=append?[...events.value,...data.items]:data.items;cursor.value=data.next_cursor}}
watch(()=>[props.accountId,props.target],()=>{events.value=[];cursor.value=null;selected.value=null;load()},{immediate:true})
</script>
<template><div :class="compact?'pa-4':'pa-5 pa-md-7'"><v-alert v-for="(e,k) in errors" v-show="e" :key="k" type="error" variant="tonal" class="mb-3">{{e}}</v-alert><div v-if="!compact"><h2 class="text-h5">Authorization audit</h2><p class="text-medium-emphasis">Immutable, account-scoped mutation history restricted by model read permissions.</p><v-row><v-col cols="12" md="3"><v-select v-model="model" :items="['groups','rbac','acl','abac','ngac']" multiple chips label="Models"/></v-col><v-col cols="12" md="3"><v-text-field v-model="action" label="Action contains"/></v-col><v-col cols="12" md="3"><v-text-field v-model="actor" label="Actor contains"/></v-col><v-col cols="12" md="3"><v-text-field v-model="targetFilter" label="Target contains"/></v-col><v-col cols="12" md="5"><v-text-field v-model="start" type="datetime-local" label="From"/></v-col><v-col cols="12" md="5"><v-text-field v-model="end" type="datetime-local" label="Through"/></v-col><v-col cols="12" md="2"><v-btn block color="primary" class="mt-2" @click="load(false)">Filter</v-btn></v-col></v-row></div><v-timeline v-if="events.length" side="end" density="compact"><v-timeline-item v-for="event in events" :key="event.event_id" :dot-color="event.model==='groups'?'cyan':'primary'" size="small"><v-card variant="outlined" @click="selected=event"><v-card-title class="text-subtitle-2">{{event.model.toUpperCase()}} · {{event.action}}</v-card-title><v-card-subtitle>{{event.actor_id}} · {{new Date(event.timestamp).toLocaleString()}}</v-card-subtitle><v-card-text class="xolo-mono text-caption">{{event.target}}</v-card-text></v-card></v-timeline-item></v-timeline><v-alert v-else-if="!loading.audit" type="info" variant="tonal">No matching authorization events.</v-alert><v-btn v-if="cursor" block variant="tonal" :loading="loading.audit" @click="load(true)">Load more</v-btn><v-dialog :model-value="!!selected" max-width="850" @update:model-value="v=>{if(!v)selected=null}"><v-card v-if="selected" title="Audit detail"><v-card-text><div class="text-caption xolo-mono mb-4">{{selected.event_id}} · {{selected.correlation_id}}</div><v-row><v-col cols="12" md="6"><h3>Before</h3><pre>{{JSON.stringify(selected.before,null,2)}}</pre></v-col><v-col cols="12" md="6"><h3>After</h3><pre>{{JSON.stringify(selected.after,null,2)}}</pre></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn @click="selected=null">Close</v-btn></v-card-actions></v-card></v-dialog></div></template>
<style scoped>pre{white-space:pre-wrap;word-break:break-word;background:#071522;padding:12px;border-radius:8px;max-height:420px;overflow:auto}</style>
